        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos I.13-14</em> <small>(c. 350 AD)</small><p>&#x27;The Lord hath said unto me, Thou art my Son; this day have I begotten thee&#x27; — Athanasius marks gegennēka se (I have begotten thee) as the eternal-generation prooftext, fielding the central Arian objection: if there was a &#x27;day&#x27; (sēmeron) of begetting, wasn&#x27;t there a &#x27;before&#x27; when the Son was not? Athanasius answers that the sēmeron of the eternal-generation is not a temporal-moment but the perpetual-now of the divine-life — the Father eternally-begets, the Son eternally-is-begotten; the &#x27;today&#x27; is an analogical-borrowing from human-generation language that does not carry the temporal-implication into the divine-relation. Tewahedo Trisagion-theology preserves the Athanasian eternal-generation-without-temporal-priority in its anti-Arian Trisagion formula.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
