    (
        22,
        1,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos III.54</em> <small>(c. 350 AD)</small><p>&#x27;My God, my God, why hast thou forsaken me?&#x27; (LXX 21:2 — ho theos ho theos mou, prosches moi, hina ti enkatelipes me) — Athanasius marks the CRY-OF-DERELICTION as voiced-by-the-assumed-flesh, NOT by the divine-Word as such. The divine-Word cannot be forsaken by the Father (Jn 16:32 — kai ouk eimi monos, hoti ho Patēr met&#x27; emou estin — &#x27;and I am not alone, for the Father is with me&#x27;); the Word remains-eternally-with-the-Father even through the cross. The cry is voiced by the Word-IN-the-flesh, redeeming-from-within the human-experience of God-forsakenness. This anti-patripassian reading is CONSTITUTIVE for Tewahedo Holy-Friday Trisagion: &#x27;Holy God who was crucified FOR US&#x27; — qua-flesh-suffered, qua-Word-impassible.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
    ),
