    (
        51,
        1,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Epistola ad Marcellinum §28</em> <small>(c. 350 AD)</small><p>&#x27;Have mercy upon me, O God, according to thy lovingkindness: according unto the multitude of thy tender mercies blot out my transgressions&#x27; (LXX 50:3) — Athanasius marks Ps 51 (LXX 50) as the PENITENTIAL-PRAYER PARADIGM in the Letter to Marcellinus: prescribed for the soul-confessing-grave-sin. The eleēson me ho theos kata to mega eleos sou (have mercy on me, O God, according-to thy great-mercy) becomes the canonical-confession-formula for the Tewahedo penitential-tradition. Athanasius&#x27;s pastoral-instruction: pray Ps 51 not as one observing-David-confessing (third-person) but as one&#x27;s-OWN-confession-in-David&#x27;s-voice. The Psalter is the Spirit-given prayer-vocabulary the praying-soul inhabits.</p></aside>',
        "Athanasius of Alexandria, Epistola ad Marcellinum de Interpretatione Psalmorum (Letter to Marcellinus on the Interpretation of the Psalms), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 27 (1857). The Letter is Athanasius's principal pastoral-spiritual work — a personal letter to Marcellinus (recovering from illness) explaining how to use each Psalm as prayer for specific spiritual circumstances. Hermeneutic anchor for the Tewahedo Office (Säʿatat) Psalter-recitation tradition.",
    ),
