    (
        82,
        6,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos III.19</em> <small>(c. 350 AD)</small><p>&#x27;I have said, Ye are gods; and all of you are children of the most High&#x27; (LXX 81:6 — egō eipa theoi este kai huioi hypsistou pantes) — Athanasius marks Ps 82:6 as the THEŌSIS-BY-GRACE anchor — explicitly cited by the Word himself at Jn 10:34-35 to silence the blasphemy-charge for his ego eimi self-identification. The human-recipients of the divine-word are called &#x27;gods&#x27; by-participation, by-grace, by-econoomic-divine-naming; the Word is God by-nature, by-essence, by-eternal-generation. Athanasius&#x27;s signature theōsis-formula in DI §54 — &#x27;He was made man that we might be made God&#x27; (autos enēnthrōpēsen hina hēmeis theopoiēthōmen) — rests on this Ps 82:6 / Exo 7:1 / 2 Pet 1:4 grammar: gods-by-grace through-the-Word who-is-God-by-nature. The Tewahedo soteriology preserves this asymmetric grammar at every catechetical level.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
    ),
